Q: How to make an array of numbers into one single number? A: <p>One alternative to using <code>std::string</code> is to use the <a href="https://stackoverflow.com/questions/5207532/appending-a-number-to-a-number">&quot;shift + append&quot; rule</a> to concatenate the numbers:</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;iostream&gt;
#include &lt;cmath&gt;
#include &lt;vector&gt;


unsigned long long combine(const std::vector&lt;unsigned int&gt;&amp; arr)
{
    unsigned long long result = 0;

    for (unsigned int num : arr)
    {
        unsigned int digits; //used to store the number of digits in the num
        //calculate the number of digits in each num 
        if(num == 0)
        {
            digits = 1;
        }
        else 
        {
            digits =  std::log10(num) + 1;
        }
        //std::cout &lt;&lt;&quot;digits in: &quot; &lt;&lt; num &lt;&lt; &quot; &quot; &lt;&lt; digits &lt;&lt; std::endl; //print for debugging

        result = result * std::pow(10, digits) + num; //shift and append 
    }

    return result;
}

int main()
{
    std::cout &lt;&lt; combine({10, 23, 4, 54, 6}) &lt;&lt; '\n';
    std::cout &lt;&lt; combine({101, 203, 2, 0, 68}) &lt;&lt; '\n';
}
</code></pre>
<p><a href="https://godbolt.org/z/sz75Eab43" rel="nofollow noreferrer">Working demo</a></p>
<hr />
<p>Note that <code>std::pow(10, digits)</code> might give surprising result (with floating point) which is one disadvantage of using this method. Also see <a href="https://stackoverflow.com/questions/15851636/why-is-my-integer-math-with-stdpow-giving-the-wrong-answer">Why is my integer math with std::pow giving the wrong answer?</a></p>

